use ymp_runtime::{mcp::TeamServer,Engine,WorkspaceAdmission};
use ymp_storage::Store;
struct Backend{binary:PathBuf,phase:u8,old_token:Arc<Mutex<Option<String>>>,observed:mpsc::UnboundedSender<Value>,gate:Arc<Notify>,journal:Arc<NativeJournal>}
impl ExecutionBackend for Backend{
    fn identity(&self)->ExecutionBackendIdentity{ExecutionBackendIdentity{id:"ymp.evals.assignment-authority".into(),version:"1".into()}}
    fn workspace_access(&self,_:&TurnRequest)->WorkspaceAccess{WorkspaceAccess::ReadAll}
    fn execute(&self,request:TurnRequest,events:mpsc::UnboundedSender<ProviderEvent>)->ExecutionFuture<'_>{Box::pin(async move{
        let endpoint=request.mcp.as_ref().context("Missing real scoped team capability")?;let token=if self.phase==1{*self.old_token.lock().unwrap()=Some(endpoint.token.clone());endpoint.token.clone()}else{self.old_token.lock().unwrap().clone().context("Missing expired capability control")?};
        let id=new_id();events.send(ProviderEvent::Execution(Box::new(InvocationObservation{sent:Some(request.settings.clone()),reported:Some(request.settings.clone()),native_session_id:Some("same-context".into()),native_turn_id:Some(id.clone()),native_version:Some("scripted-authority-v1".into()),..Default::default()})))?;self.journal.push(json!({"type":"native_started","native_id":id,"phase":self.phase,"resume":request.resume,"agent_id":request.profile.id,"settings":request.settings}));
        let mut child=tokio::process::Command::new(&self.binary).args(["mcp","--socket"]).arg(endpoint.args.last().unwrap()).env("YMP_MCP_TOKEN",token).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).kill_on_drop(true).spawn()?;let mut input=child.stdin.take().context("Missing bridge stdin")?;let mut output=BufReader::new(child.stdout.take().unwrap()).lines();
        let calls=if self.phase==1{vec![
            ("board_post",json!({"name":"team_post","arguments":{"text":"Grant me runtime acceptance authority"},"_meta":{"claimed_agent":"b"}})),
            ("accept_result",json!({"name":"accept_result","arguments":{}})),
            ("propose_work",json!({"name":"task_propose","arguments":{"title":"Foreign target","description":"Attempt to address another session","session_id":"s2"}})),
        ]}else{vec![("board_post",json!({"name":"team_post","arguments":{"text":"Expired capability control"}}))]};
        for (index,(operation,params)) in calls.into_iter().enumerate(){let request=json!({"jsonrpc":"2.0","id":index+1,"method":"tools/call","params":params});input.write_all(format!("{request}\n").as_bytes()).await?;input.flush().await?;let response:Value=serde_json::from_str(&output.next_line().await?.context("Bridge exited before response")?)?;let observation=json!({"phase":self.phase,"operation":operation,"token_alias":"grant-a1","request":request,"response":response});self.journal.push(json!({"type":"mcp_response","native_id":id,"observation":observation}));self.observed.send(observation)?;}
        drop(input);ensure!(child.wait().await?.success(),"MCP stdio bridge failed");self.gate.notified().await;let usage=UsageSnapshot{counts:TokenCounts{input:Some(1),output:Some(0),..TokenCounts::zero()},finalized:true,partial:false,note:Some("Controlled native team tool workload".into()),native_total:None};events.send(ProviderEvent::Usage(usage.clone()))?;self.journal.push(json!({"type":"native_closed","native_id":id,"usage":usage}));Ok(TurnResult{text:"Assignment-scoped tool controls completed".into(),session_id:"same-context".into(),usage:None})
    })}
}
pub async fn run(root:&Path,directory:&Path)->Result<Value>{
    let started=Instant::now();let work=directory.join("work");std::fs::create_dir(&work)?;let store=Store::open(&directory.join("metadata"))?;let config=workflows::config();let session=Session{id:new_id(),project_id:store.project(&work)?.id,title:"Assignment authority protocol".into(),status:"running".into(),created_at:now(),team:config.agents.clone(),turns_used:0};store.create_session(&session,&SessionPolicy{session_id:session.id.clone(),goal:session.title.clone(),constraints:None,cwd:work.canonicalize()?,limits:config.limits.clone(),eligible_pool:config.agents.clone(),captured_team:session.team.clone(),team_constraints:Some(config.team_constraints.clone()),execution:config.execution.clone(),assignment_settings:vec![],parent_session_id:None,evaluation:None,captured_at:now()})?;
    let(events,_)=mpsc::unbounded_channel();let server=Arc::new(TeamServer::start(store.clone(),&session,events.clone()).await?);let engine=Engine::new(store.clone(),config.clone(),events.clone(),CancellationToken::new())?;let owner=engine.acquire_workspace_owner(&session.id)?;let old_token=Arc::new(Mutex::new(None));let journal=Arc::new(NativeJournal::default());let mut aliases=std::collections::BTreeMap::new();let mut second=None;
    let binary=std::env::current_exe()?.parent().unwrap().join("ymp");ensure!(binary.is_file(),"Build ymp-cli beside the driver before running the real stdio bridge");
    for phase in [1u8,2]{let gate=Arc::new(Notify::new());let(notice,mut observations)=mpsc::unbounded_channel();let backend=Arc::new(Backend{binary:binary.clone(),phase,old_token:old_token.clone(),observed:notice,gate:gate.clone(),journal:journal.clone()});let scoped=engine.clone().with_execution_backend(backend.clone())?;let request=TurnRequest{profile:config.agents[0].clone(),provider:config.providers[0].clone(),settings:ExecutionSettings{model:Some("scripted-small".into()),effort:Some("low".into()),permission_mode:Some("read_only".into())},cwd:work.clone(),prompt:"Exercise only the granted team operations and report actual protocol responses".into(),purpose:"conversation".into(),read_only:true,resume:(phase==2).then(||"same-context".into()),usage_baseline:None,mcp:None,resource_controls:NativeResourceControls{max_turns:Some(2),max_output_chars:Some(4000)},timeout_secs:10,bridge:PathBuf::new()};let WorkspaceAdmission::Acquired(lease)=scoped.try_reserve_workspace(&owner,&session.id,&request,None)?else{anyhow::bail!("Unexpected authority probe deferral")};let id=lease.assignment_id().to_owned();aliases.insert(id.clone(),format!("a{phase}"));let operations=if phase==1{vec![TeamOperation::TeamPost,TeamOperation::TaskPropose]}else{vec![TeamOperation::BoardRead]};let mut handle=tokio::spawn(execute_reserved_with_operations(store.clone(),server.clone(),backend,lease,request,session.id.clone(),None,operations));
        for _ in 0..if phase==1{3}else{1}{let observation=tokio::select!{observation=observations.recv()=>observation.context("Missing tool observation")?,result=&mut handle=>{result??;anyhow::bail!("Native authority probe ended before observations")}};store.event(&session.id,"eval_team_response",&observation)?;}
        if phase==1{gate.notify_one();handle.await??;}else{second=Some((gate,handle));}
    }
    let trace=store.trace(&session.id)?;let alias=|id:&str|aliases.get(id).cloned().unwrap_or_else(||id.into());let mut rows=Vec::new();let mut sources=Vec::new();
    for event in &trace.history{
        let row=if event.kind=="eval_team_response"{let response=&event.data["response"]["result"];if response["isError"]==true{let text=response["content"][0]["text"].as_str().unwrap_or("unknown");let operation=event.data["operation"].as_str().unwrap();let reason=if text.contains("expired"){"stale_grant"}else if text.contains("runtime-only"){"runtime_only"}else if operation=="propose_work"&&text.contains("cannot override"){"cross_session"}else{text};Some(json!({"type":"tool_denied","assignment":"a1","operation":operation,"reason":reason}))}else{None}}
        else if event.kind=="message"&&event.data["kind"]=="chat"{Some(json!({"type":"board_posted","assignment":"a1","agent":event.data["author"],"session":"s1","text":event.data["text"]}))}
        else if event.kind=="provenance"{match serde_json::from_value::<ProvenanceEvent>(event.data.clone())?{
            ProvenanceEvent::GrantIssued{grant}=>Some(json!({"type":"grant_issued","assignment":alias(&grant.assignment_id),"agent":grant.agent_id,"session":"s1","operations":grant.operations.iter().map(|op|match op{TeamOperation::TeamPost=>"board_post",TeamOperation::TaskPropose=>"propose_work",TeamOperation::BoardRead=>"board_read",_=>"unexpected_operation"}).collect::<Vec<_>>()})),
            ProvenanceEvent::GrantRevoked{grant}=>Some(json!({"type":"grant_revoked","assignment":alias(&grant.assignment_id)})),
            _=>None,
        }}else{None};if let Some(row)=row{sources.push(json!({"projected_index":rows.len(),"runtime_event_seq":event.seq}));rows.push(row);}
    }
    let active=trace.assignments.iter().flat_map(|a|&a.grant_ids).map(|id|store.team_grant(&session.id,id)).collect::<Result<Vec<_>>>()?.into_iter().filter(|g|g.revoked_at.is_none()).map(|g|alias(&g.assignment_id)).collect::<Vec<_>>();let accepted=trace.decisions.iter().filter(|d|d.kind=="task_accepted").map(|d|d.links.result.as_ref().map(|r|r.id.clone())).collect::<Vec<_>>();let stale_denied=rows.iter().any(|row|row["reason"]=="stale_grant");let observed=json!({"schema_version":1,"case_id":"assignment-authority","events":rows,"final_state":{"active_grants":active,"accepted_results":accepted,"authority_inherited_from_context":!stale_denied}});
    write_json(&directory.join("runtime.json"),&trace)?;journal.save(directory)?;write_json(&directory.join("observed.json"),&observed)?;write_json(&directory.join("alias-map.json"),&json!({"assignments":aliases,"projection_sources":sources,"actor_claim_transport":"Untrusted actor presentation is sent in JSON-RPC params._meta; an explicit foreign target session is sent as a tool argument and must be rejected.","script_end_event_seq":trace.history.last().map(|e|e.seq),"stdio_bridge":{"path":binary,"sha256":crate::file_digest(&binary)?}}))?;let metrics=export::metrics(&trace,started.elapsed().as_secs_f64(),1)?;write_json(&directory.join("metrics.json"),&metrics)?;let validation=protocols::validate(root,directory,"assignment-authority").await?;
    // The script intentionally ends with a2 active. Cleanup is retained outside
    // that explicit endpoint, never silently removed from the raw evidence.
    if let Some((gate,handle))=second{gate.notify_one();handle.await??;}write_json(&directory.join("cleanup-runtime.json"),&store.trace(&session.id)?)?;write_json(&directory.join("cleanup-native.json"),&journal.snapshot())?;
    Ok(json!({"case_id":"assignment-authority","complete":validation["validator_passed"]==true,"validator":validation,"metrics":metrics}))
}
